<script setup>
import { ref } from 'vue';
import MButton from '../../../components/mds/MButton.vue';
import MDialog from '../../../components/mds/MDialog.vue';
import MEmptyState from '../../../components/mds/MEmptyState.vue';
import MMobileTopBar from '../../../components/mds/MMobileTopBar.vue';
import MTag from '../../../components/mds/MTag.vue';
import MTabs from '../../../components/mds/MTabs.vue';
import PartnerCooperationFilesPanel from '../PartnerCooperationFilesPanel.vue';

const props = defineProps({ detail: { type: Object, required: true }, safeAreaStyle: { type: Object, default: () => ({}) }, canEdit: { type: Boolean, default: false }, canDelete: { type: Boolean, default: false }, canCreateCooperation: { type: Boolean, default: false }, canEditCooperation: { type: Function, default: () => false }, canReassignCooperation: { type: Function, default: () => false }, canUploadCooperation: { type: Function, default: () => false }, canDeleteCooperation: { type: Boolean, default: false }, deletingCooperationId: { type: Number, default: null }, uploadingCooperationId: { type: Number, default: null }, cooperationDeleteError: { type: String, default: '' }, fileError: { type: String, default: '' }, deleteWorking: { type: Boolean, default: false }, deleteError: { type: String, default: '' } });
const emit = defineEmits(['back', 'navigate', 'edit', 'create-agreement', 'create-work-log', 'edit-agreement', 'edit-work-log', 'reassign-agreement', 'reassign-work-log', 'upload-agreement', 'upload-work-log', 'delete-agreement', 'delete-work-log', 'delete-partner']);
const activeTab = ref('overview');
const deleteOpen = ref(false);
const cooperationDeleteTarget = ref(null);
const cooperationDeleteOpen = ref(false);
const tabs = [{ key: 'overview', label: 'Thông tin' }, { key: 'people', label: 'Nhân sự' }, { key: 'dates', label: 'Nhắc lịch' }, { key: 'cooperation', label: 'Hợp tác' }];
function requestCooperationDelete(type, item) { cooperationDeleteTarget.value = { type, id: item.id, title: item.title }; cooperationDeleteOpen.value = true; }
function confirmCooperationDelete() { if (cooperationDeleteTarget.value?.type === 'agreement') emit('delete-agreement', cooperationDeleteTarget.value.id); else if (cooperationDeleteTarget.value?.type === 'work-log') emit('delete-work-log', cooperationDeleteTarget.value.id); }
</script>

<template>
  <section class="mds-mobile-app flex h-[100dvh] min-w-0 flex-col overflow-hidden bg-[var(--mds-bg)] text-[var(--mds-text)]" :style="safeAreaStyle">
    <MMobileTopBar :title="detail.name" @back="emit('back')"><template v-if="canEdit" #actions><MButton variant="link" @click="emit('edit')">Sửa</MButton></template></MMobileTopBar>
    <div class="mds-mobile-gutter-x shrink-0 border-b border-[var(--mds-border-light)] py-3"><p class="truncate text-[14px] font-medium leading-5">{{ detail.subtitle }}</p><MTag color="brand" class="mt-1">{{ detail.typeLabel }}</MTag></div>
    <MTabs v-model="activeTab" :tabs="tabs" class="flex min-h-0 flex-1 flex-col [&>[role=tablist]]:shrink-0 [&>[role=tablist]]:overflow-x-auto [&>[role=tablist]]:whitespace-nowrap [&>[role=tablist]]:px-4 [&>[role=tabpanel]]:min-h-0 [&>[role=tabpanel]]:flex-1 [&>[role=tabpanel]]:overflow-y-auto">
      <div v-if="activeTab === 'overview'"><dl class="mds-mobile-gutter-x pb-4"><div v-for="field in detail.fields" :key="field[0]" class="mds-mobile-row-gap-4 flex min-h-[var(--mds-mobile-touch-target)] items-center gap-4 border-b border-[var(--mds-border-light)] py-2"><dt class="w-[132px] shrink-0 text-[13px] leading-[18px] text-[var(--mds-text-secondary)]">{{ field[0] }}</dt><dd class="mds-mobile-readable min-w-0 flex-1 break-words text-right text-[13px] font-medium leading-[18px]">{{ field[1] }}</dd></div></dl><div v-if="canDelete" class="mds-mobile-gutter-x pb-6"><p v-if="deleteError" role="alert" class="mb-3 rounded-lg bg-[var(--mds-danger-bg)] px-3 py-2 text-[13px] leading-[18px] text-[var(--mds-danger)]">{{ deleteError }}</p><MButton variant="danger" class="w-full" :disabled="deleteWorking" @click="deleteOpen = true">Xóa cơ quan</MButton></div></div>
      <section v-else-if="activeTab === 'people'" class="px-4 pb-5"><div v-if="detail.people.length" class="divide-y divide-[var(--mds-border-light)]"><MButton v-for="person in detail.people" :key="person.id" variant="link" class="flex min-h-[64px] h-auto w-full items-center justify-between gap-4 rounded-none py-2 text-left" @click="emit('navigate', person.id)"><span class="min-w-0"><strong class="block truncate text-[14px]">{{ person.name }}</strong><span class="mt-1 block truncate text-[13px] text-[var(--mds-text-secondary)]">{{ person.role }}</span></span><span class="shrink-0 text-[var(--mds-brand-600)]" aria-hidden="true">›</span></MButton></div><MEmptyState v-else title="Chưa có nhân sự" description="Nhân sự được tạo trong luồng quản lý danh bạ." /></section>
      <section v-else-if="activeTab === 'dates'" class="px-4 pb-5"><div v-if="detail.dates.length" class="divide-y divide-[var(--mds-border-light)]"><div v-for="date in detail.dates" :key="date.id" class="flex min-h-[64px] items-center justify-between gap-4 py-2"><span class="min-w-0"><strong class="block truncate text-[14px]">{{ date.title }}</strong><span v-if="date.recurring" class="mt-1 block text-[13px] text-[var(--mds-text-secondary)]">Lặp lại hằng năm</span></span><span class="shrink-0 text-[13px] font-medium">{{ date.date }}</span></div></div><MEmptyState v-else title="Chưa có ngày nhắc" description="Ngày thành lập và các mốc hợp tác sẽ xuất hiện tại đây khi được tạo." /></section>
      <section v-else class="space-y-5 px-4 pb-5"><div><div class="flex items-center justify-between gap-3 pt-4"><h2 class="text-[16px] font-semibold">Thỏa thuận / MOU</h2><MButton v-if="canCreateCooperation" variant="link" @click="emit('create-agreement')">Thêm MOU</MButton></div><div v-if="detail.agreements.length" class="mt-2 divide-y divide-[var(--mds-border-light)]"><div v-for="agreement in detail.agreements" :key="agreement.id" class="flex min-h-[64px] items-center justify-between gap-3 py-2"><span class="min-w-0"><strong class="block truncate text-[14px]">{{ agreement.title }}</strong><span class="mt-1 block text-[13px] text-[var(--mds-text-secondary)]">Ký {{ agreement.signedDate }} · Đến {{ agreement.validUntil }}</span></span><span class="flex shrink-0 items-center gap-2"><MButton v-if="canEditCooperation(agreement)" variant="link" @click="emit('edit-agreement', agreement)">Sửa</MButton><MButton v-if="canReassignCooperation(agreement)" variant="link" @click="emit('reassign-agreement', agreement)">Gán</MButton><MButton v-if="canDeleteCooperation" variant="link" :disabled="deletingCooperationId === agreement.id" @click="requestCooperationDelete('agreement', agreement)">Xóa</MButton></span></div></div><MEmptyState v-else title="Chưa có thỏa thuận" description="Tạo thỏa thuận để theo dõi ngày ký và thời hạn hiệu lực." /></div><div><div class="mt-5 flex items-center justify-between gap-3"><h2 class="text-[16px] font-semibold">Lịch sử làm việc</h2><MButton v-if="canCreateCooperation" variant="link" @click="emit('create-work-log')">Ghi nhận</MButton></div><div v-if="detail.workLogs.length" class="mt-2 divide-y divide-[var(--mds-border-light)]"><div v-for="work in detail.workLogs" :key="work.id" class="flex min-h-[64px] items-center justify-between gap-3 py-2"><span class="min-w-0"><strong class="block truncate text-[14px]">{{ work.title }}</strong><span class="mt-1 block text-[13px] text-[var(--mds-text-secondary)]">{{ work.category }} · {{ work.date }} · {{ work.status }}</span></span><span class="flex shrink-0 items-center gap-2"><MButton v-if="canEditCooperation(work)" variant="link" @click="emit('edit-work-log', work)">Sửa</MButton><MButton v-if="canReassignCooperation(work)" variant="link" @click="emit('reassign-work-log', work)">Gán</MButton><MButton v-if="canDeleteCooperation" variant="link" :disabled="deletingCooperationId === work.id" @click="requestCooperationDelete('work-log', work)">Xóa</MButton></span></div></div><MEmptyState v-else title="Chưa có lịch sử làm việc" description="Ghi nhận các buổi làm việc để có lịch sử theo dõi chung." /></div><PartnerCooperationFilesPanel :agreements="detail.agreements" :work-logs="detail.workLogs" :can-upload="canUploadCooperation" :uploading-id="uploadingCooperationId" :error="fileError" @upload-agreement="emit('upload-agreement', $event)" @upload-work-log="emit('upload-work-log', $event)" /><p v-if="props.cooperationDeleteError" role="alert" class="rounded-lg bg-[var(--mds-danger-bg)] px-3 py-2 text-[13px] leading-[18px] text-[var(--mds-danger)]">{{ props.cooperationDeleteError }}</p></section>
    </MTabs>
    <MDialog v-model="deleteOpen" title="Xóa cơ quan?" type="danger" confirm-text="Xóa cơ quan" @confirm="emit('delete-partner')"><p>Hồ sơ cơ quan và các dữ liệu liên quan có thể bị xóa. Thao tác này không thể hoàn tác.</p></MDialog>
    <MDialog v-model="cooperationDeleteOpen" :title="cooperationDeleteTarget?.type === 'agreement' ? 'Xóa thỏa thuận?' : 'Xóa lịch sử làm việc?'" type="danger" confirm-text="Xóa" @confirm="confirmCooperationDelete"><p>“{{ cooperationDeleteTarget?.title }}” sẽ bị xóa. Thao tác này không thể hoàn tác.</p></MDialog>
  </section>
</template>
